insert into exercises (id, name, description) values
  ('world-s-greatest-stretch', 'World''s Greatest Stretch', 'Lunge forward, drop the opposite elbow to your instep, then rotate the chest open.'),
  ('squat-reach', 'Squat & Reach', 'Hold a deep squat and reach one arm overhead, opening through the upper back.'),
  ('90-90s', '90/90s', 'Sit with both knees bent 90 degrees and rotate the hips side to side to open them.'),
  ('banded-glute-bridges', 'Banded Glute Bridges', 'Band above the knees, bridge the hips up squeezing glutes while pressing knees out.'),
  ('banded-pull-aparts', 'Banded Pull-aparts', 'Hold a band at shoulder height and pull it apart, squeezing the shoulder blades.'),
  ('split-squat-hold', 'Split Squat Hold', 'Hold the bottom of a split-stance lunge, front thigh parallel and torso tall.'),
  ('barbell-box-squat', 'Barbell Box Squat', 'Squat back to lightly touch a box, then drive up through the heels.'),
  ('barbell-overhead-press', 'Barbell Overhead Press', 'Press the weight overhead from the shoulders to a full lockout, ribs down.'),
  ('single-arm-kb-row', 'Single-arm KB Row', 'Supported on one arm, row the weight to the hip, squeezing the shoulder blade.'),
  ('squat-jumps', 'Squat Jumps', 'Dip into a quarter squat and jump explosively, landing soft through the knees.'),
  ('hollow-hold', 'Hollow Hold', 'Lie on your back, lift the shoulders and legs, pressing the low back into the floor.'),
  ('db-tibialis-anterior-raises', 'DB Tibialis Anterior Raises', 'Heels down, pull the toes up toward the shins against load, then lower slowly.'),
  ('db-single-leg-calf-raises', 'DB Single-leg Calf Raises', 'Rise onto the ball of one foot, then lower the heel slowly below the step.'),
  ('90-90', '90/90', 'Sit with both knees bent 90 degrees and rotate the hips side to side to open them.'),
  ('db-box-squat', 'DB Box Squat', 'Squat back to lightly touch a box, then drive up through the heels.'),
  ('db-shoulder-press', 'DB Shoulder Press', 'Press the weight overhead from the shoulders to a full lockout, ribs down.'),
  ('single-arm-db-row', 'Single-arm DB Row', 'Supported on one arm, row the weight to the hip, squeezing the shoulder blade.'),
  ('single-leg-glute-bridge', 'Single-leg Glute Bridge', 'Drive through one heel to lift the hips level, squeeze at the top, then lower with control.'),
  ('prone-w-raise', 'Prone W-Raise', 'Face down with elbows tucked into a W, lift the hands and squeeze the shoulder blades together.'),
  ('box-squat-to-a-chair', 'Box Squat (to a chair)', 'Sit back to lightly touch a chair, stay tight, then stand tall. Add a band above the knees if you have one.'),
  ('pike-push-up', 'Pike Push-up', 'Hips high in an inverted V, lower the crown of the head toward the floor, then press up. Add a band over the back for load if available.'),
  ('prone-floor-row-y-t-w', 'Prone Floor Row (Y-T-W)', 'Face down, sweep the arms through Y, T and W shapes just off the floor, squeezing the upper back. Anchor a band underfoot to add load if available.'),
  ('wall-tibialis-raise', 'Wall Tibialis Raise', 'Lean your back on a wall with heels planted, pull the toes up toward the shins, then lower slowly.'),
  ('eccentric-single-leg-calf-raises', 'Eccentric Single-leg Calf Raises', 'Rise onto the ball of one foot, then lower the heel slowly below the step.'),
  ('barbell-tempo-deadlift', 'Barbell Tempo Deadlift', 'Deadlift with a slow controlled lower, flat back, then drive the floor away to stand.'),
  ('barbell-bench-press', 'Barbell Bench Press', 'Lower the weight to the chest with control, then press back up to lockout.'),
  ('lat-pulldown', 'Lat Pulldown', 'Pull the band or bar down toward the chest, driving the elbows to the ribs.'),
  ('lateral-skater-bounds', 'Lateral Skater Bounds', 'Bound side to side off one leg, landing softly and holding balance each side.'),
  ('db-tempo-deadlift', 'DB Tempo Deadlift', 'Deadlift with a slow controlled lower, flat back, then drive the floor away to stand.'),
  ('db-bench-press', 'DB Bench Press', 'Lower the weight to the chest with control, then press back up to lockout.'),
  ('db-pullover', 'DB Pullover', 'Lie back and lower a dumbbell behind the head, then pull it back over the chest.'),
  ('bodyweight-tempo-rdl', 'Bodyweight Tempo RDL', 'Hinge with a slow controlled lower and a flat back, then drive the floor away to stand tall.'),
  ('push-up', 'Push-up', 'Lower the chest to the floor with elbows about 45 degrees, then press back up in a straight line.'),
  ('prone-floor-lat-pulldown', 'Prone Floor Lat Pulldown', 'Lie face down with arms overhead and pull the elbows down toward the ribs while lifting the chest, squeezing the lats.'),
  ('barbell-bulgarian-split-squat', 'Barbell Bulgarian Split Squat', 'Rear foot on a bench, lower straight down on the front leg, then drive up tall.'),
  ('half-kneeling-single-arm-landmine-press', 'Half-kneeling Single-Arm Landmine Press', 'Half-kneeling, press the weight overhead one arm at a time, torso tall.'),
  ('pull-ups-weighted-negatives', 'Pull-ups (weighted / negatives)', 'Hang from a bar and pull your chin over it; add load or lower slowly.'),
  ('box-jumps', 'Box Jumps', 'Jump from a soft quarter squat onto a box, landing quietly with bent knees.'),
  ('db-bulgarian-split-squat', 'DB Bulgarian Split Squat', 'Rear foot on a bench, lower straight down on the front leg, then drive up tall.'),
  ('half-kneeling-single-arm-db-press', 'Half-kneeling Single-Arm DB Press', 'Half-kneeling, press the weight overhead one arm at a time, torso tall.'),
  ('db-bent-over-row', 'DB Bent Over Row', 'Hinge forward with a flat back and row the weight to the ribs, elbows tucked.'),
