  ('banded-air-squats', 'Banded Air Squats', 'Loop a band above the knees and squat, pushing the knees out throughout.'),
  ('banded-monster-walks', 'Banded Monster Walks', 'Band above the knees in a half-squat, step out and forward keeping tension.'),
  ('single-leg-rdl-kb', 'Single-leg RDL (KB)', 'Hinge over one leg lowering the weight with a flat back, then stand and squeeze.'),
