  ('bodyweight-squat-tempo', 'Bodyweight Squat (tempo)', 'Squat to depth with a slow lower and controlled stand, knees pushing out. Add a band above the knees if available.'),
  ('side-lying-hip-abduction', 'Side-lying Hip Abduction', 'Lie on your side and lift the top leg with control, hips stacked. Add a band above the knees if available.'),
  ('single-leg-rdl', 'Single-leg RDL', 'Hinge over one leg with a flat back, reaching toward the floor, then stand and squeeze the glute. Hold a bag if available.'),
  ('side-plank-knee-drive', 'Side Plank Knee Drive', 'Hold a side plank and drive the top knee toward the chest, keeping the ribs stacked.'),
  ('db-goblet-cyclist-squat', 'DB Goblet Cyclist Squat', 'Heels elevated, hold the weight at the chest and squat deep, knees tracking forward.'),
  ('single-leg-hops', 'Single-leg Hops', 'Hop forward on one leg, staying tall and springing off the ball of the foot.'),
  ('copenhagen-plank', 'Copenhagen Plank', 'Side plank with the top leg on a bench, holding the hips lifted through the inner thigh.'),
  ('explosive-single-leg-hops', 'Explosive Single-leg Hops', 'Hop forward on one leg, staying tall and springing off the ball of the foot.'),
  ('heel-elevated-squat', 'Heel-elevated Squat', 'Heels raised on a book or plate, squat deep with an upright chest and knees tracking over the toes.'),
  ('barbell-b-stance-rdl', 'Barbell B-stance RDL', 'Kickstand stance, hinge over the front leg with most of the weight through it.'),
  ('copenhagen-plank-top-leg-raise', 'Copenhagen Plank (top-leg raise)', 'Side plank with the top leg on a bench, holding the hips lifted through the inner thigh.'),
  ('db-single-leg-calf-raises-deficit', 'DB Single-leg Calf Raises (deficit)', 'Rise onto the ball of one foot, then lower the heel slowly below the step.'),
  ('db-b-stance-rdl', 'DB B-stance RDL', 'Kickstand stance, hinge over the front leg with most of the weight through it.'),
  ('b-stance-rdl', 'B-stance RDL', 'Stagger the feet, hinge back over the front leg with a flat back, then squeeze to stand. Hold a bag for load if you like.'),
  ('eccentric-single-leg-calf-raises-deficit', 'Eccentric Single-leg Calf Raises (deficit)', 'Rise onto the ball of one foot, then lower the heel slowly below the step.'),
  ('banded-strict-press', 'Banded Strict Press', 'Press the weight overhead from the shoulders to a full lockout, ribs down.'),
  ('banded-upright-rows', 'Banded Upright Rows', 'Stand on the band and pull the handles up to chest height, elbows leading.'),
  ('barbell-overhead-press-into-barbell-push-press', 'Barbell Overhead Press into Barbell Push Press', 'Strict press until reps stall, then push press the rest using leg drive.'),
  ('med-ball-slams', 'Med Ball Slams', 'Lift a ball overhead and slam it to the floor, hinging through the hips.'),
  ('db-shoulder-press-into-db-push-press', 'DB Shoulder Press into DB Push Press', 'Strict press until reps stall, then push press the rest using leg drive.'),
  ('prone-y-raise', 'Prone Y-Raise', 'Face down with arms overhead in a Y, lift the thumbs toward the ceiling and squeeze the lower traps.'),
  ('squat-jump', 'Squat Jump', 'Dip to a quarter squat and jump explosively, landing soft and quiet before the next rep.'),
  ('barbell-bent-over-row', 'Barbell Bent Over Row', 'Hinge forward with a flat back and row the weight to the ribs, elbows tucked.'),
  ('banded-pallof-press', 'Banded Pallof Press', 'Press a band straight out from the chest and resist it pulling you into rotation.'),
  ('rotational-med-ball-throws', 'Rotational Med Ball Throws', 'Rotate through the hips and throw a ball into a wall, then reset and repeat.'),
  ('dumbbell-woodchops', 'Dumbbell Woodchops', 'Hold a dumbbell in both hands and sweep it diagonally from hip to opposite shoulder, rotating through the trunk.'),
  ('dead-bug', 'Dead Bug', 'On your back, extend the opposite arm and leg while pressing the low back into the floor, resisting any twist.'),
  ('bear-plank-with-reach', 'Bear Plank with Reach', 'Hold a bear plank with knees hovering just off the floor, then reach one arm forward without letting the hips rotate.'),
  ('hanging-knee-raises', 'Hanging Knee Raises', 'Hang from a bar and raise the knees toward the chest, controlling the swing.'),
  ('lying-leg-raises', 'Lying Leg Raises', 'Lie on your back, raise straight legs toward the ceiling, then lower them slowly without arching the lower back.'),
  ('incline-barbell-press', 'Incline Barbell Press', 'On an incline, press the weight from the upper chest to lockout overhead.'),
