  ('incline-db-press', 'Incline DB Press', 'On an incline, press the weight from the upper chest to lockout overhead.'),
  ('feet-elevated-push-up', 'Feet-elevated Push-up', 'Feet raised on a step, lower the chest with control and press back up, body in a straight line.'),
  ('barbell-push-press', 'Barbell Push Press', 'Dip the knees and drive the weight overhead, using the legs to start the press.'),
  ('db-push-press', 'DB Push Press', 'Dip the knees and drive the weight overhead, using the legs to start the press.'),
  ('weighted-push-ups', 'Weighted Push-ups', 'Press-up with added load, lowering the chest with control and locking out on top.'),
  ('deficit-db-push-ups', 'Deficit DB Push-ups', 'Press-up with added load, lowering the chest with control and locking out on top.'),
  ('explosive-jump-squat', 'Explosive Jump Squat', 'Dip into a quarter squat and jump explosively, landing soft through the knees.'),
  ('world-s-greatest-stretch-flow', 'World''s Greatest Stretch flow', 'Flowing lunge to instep with a thoracic rotation, repeating side to side.'),
  ('half-kneeling-sa-landmine-press', 'Half-kneeling SA Landmine Press', 'Half-kneeling, press the weight overhead one arm at a time, torso tall.'),
  ('half-kneeling-sa-db-press', 'Half-kneeling SA DB Press', 'Half-kneeling, press the weight overhead one arm at a time, torso tall.'),
  ('barbell-hip-thrust', 'Barbell Hip Thrust', 'Shoulders on a bench, drive the hips up to lockout, squeezing the glutes hard.'),
  ('db-hip-thrust', 'DB Hip Thrust', 'Shoulders on a bench, drive the hips up to lockout, squeezing the glutes hard.'),
  ('bodyweight-hip-thrust', 'Bodyweight Hip Thrust', 'Shoulders on a bench, drive the hips up to lockout, squeezing the glutes hard.'),
