insert into programmes (id, family, family_label, name, sport_type, days_per_week, duration_weeks, short_description, full_description, deload_note, sort_order) values
  ('get-strong-full-body-1', 'get_strong', 'Get Strong', 'Full Body (1-Day)', 'strength', 1, 12, 'Whole-body strength in one session.', 'One efficient full-body session a week covering hips, back, pressing and single-leg work, plus mobility, activation and a touch of power. The most time-friendly way to get stronger and stay injury-resistant.', 'Cut back: 2 sets per lift at ~60% load, halve plyo & power volume, keep mobility + foot work', 1),
  ('get-strong-upper-lower-2', 'get_strong', 'Get Strong', 'Upper / Lower (2-Day)', 'strength', 2, 12, 'Two focused days a week.', 'One lower-body day and one upper-body day. Enough to build genuine strength and support your running, while leaving plenty of room for your miles.', 'Cut back: 2 sets per lift at ~60% load, halve plyo & power volume, keep mobility + foot work', 2),
  ('get-strong-ppl-3', 'get_strong', 'Get Strong', 'Push / Pull / Legs (3-Day)', 'strength', 3, 12, 'The classic push, pull, legs split.', 'Three sessions a week, one each for pushing, pulling and legs. More focused volume per area to build strength and power, with every day kept fresh and specific.', 'Cut back: 2 sets per lift at ~60% load, halve plyo & power volume, keep mobility + foot work', 3),
  ('get-strong-ulf-3', 'get_strong', 'Get Strong', 'Upper / Lower / Full (3-Day)', 'strength', 3, 12, 'Balanced strength, three ways.', 'An upper day, a lower day and a full-body day. A well-rounded week that spreads the work evenly and keeps your legs fresh for running.', 'Cut back: 2 sets per lift at ~60% load, halve plyo & power volume, keep mobility + foot work', 4),
  ('get-strong-upper-lower-4', 'get_strong', 'Get Strong', 'Upper / Lower (4-Day)', 'strength', 4, 12, 'Upper and lower, twice each.', 'Four days a week: two upper and two lower sessions, each with its own emphasis across chest, back, glutes, hamstrings and core. Serious strength for when you can give it four days.', 'Cut back: 2 sets per lift at ~60% load, halve plyo & power volume, keep mobility + foot work', 5),
  ('get-strong-full-split-5', 'get_strong', 'Get Strong', 'Full Split (5-Day)', 'strength', 5, 12, 'Five days, maximum strength focus.', 'Push, pull and legs plus dedicated upper and lower days. Our most complete week for building strength and power, with the volume spread so nothing gets overcooked.', 'Cut back: 2 sets per lift at ~60% load, halve plyo & power volume, keep mobility + foot work', 6);
